<?php
namespace App\Services;use App\Models\{TrainingAudit,TrainingProgram};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;class TrainingProgramService{public function __construct(private TrainingRegulationService$rules){}public function submit(TrainingProgram$p,int$user):void{$this->editable($p);$errors=$this->rules->validateTrainingProgram($p);if($errors)throw ValidationException::withMessages(['program'=>$errors]);$p->update(['status'=>'in_review','updated_by'=>$user]);$this->audit($p,'training_program_reviewed',$user);}public function approve(TrainingProgram$p,int$user,?string$justification):void{if($p->status!=='in_review')throw ValidationException::withMessages(['status'=>'Solo un programa en revisión puede aprobarse.']);$errors=array_merge($this->rules->validateTrainingProgram($p),$this->rules->validateProgramReview($p));if($errors)throw ValidationException::withMessages(['program'=>$errors]);$critical=$p->company->trainingNeeds()->whereIn('priority',['high','critical'])->whereDoesntHave('programItems')->exists();if($critical&&!$justification)throw ValidationException::withMessages(['justification'=>'Existen necesidades prioritarias sin programar. Registre una justificación para continuar.']);DB::transaction(function()use($p,$user,$justification){$p->update(['status'=>'approved','approved_at'=>now(),'approved_by'=>$user,'approval_justification'=>$justification]);$this->audit($p,'training_program_approved',$user,['justification'=>$justification]);});}public function activate(TrainingProgram$p,int$user):void{if($p->status!=='approved')throw ValidationException::withMessages(['status'=>'El programa debe estar aprobado.']);DB::transaction(function()use($p,$user){TrainingProgram::where('company_id',$p->company_id)->where('year',$p->year)->where('status','active')->whereKeyNot($p->id)->update(['status'=>'superseded']);$p->update(['status'=>'active','updated_by'=>$user]);$this->audit($p,'training_program_activated',$user);});}public function version(TrainingProgram$p,int$user):TrainingProgram{return DB::transaction(function()use($p,$user){$copy=$p->replicate(['status','approved_at','approved_by','approval_justification']);$copy->version=TrainingProgram::where('company_id',$p->company_id)->where('year',$p->year)->max('version')+1;$copy->status='draft';$copy->created_by=$user;$copy->updated_by=$user;$copy->save();foreach($p->items as$item){$new=$item->replicate();$new->training_program_id=$copy->id;$new->status='planned';$new->save();$activeNeeds=$item->needs()->whereNotIn('status',['addressed','cancelled'])->pluck('training_needs.id');$new->needs()->sync($activeNeeds);}$this->audit($copy,'training_program_version_created',$user,['source'=>$p->id]);return$copy;});}public function editable($p){if(!in_array($p->status,['draft','in_review']))throw ValidationException::withMessages(['program'=>'Una versión aprobada o activa no puede modificarse.']);}private function audit($p,$e,$u,$m=[]){TrainingAudit::create(['company_id'=>$p->company_id,'event'=>$e,'subject_type'=>'training_program','subject_id'=>$p->id,'user_id'=>$u,'metadata'=>$m,'created_at'=>now()]);}}
